import type { Fact, WalkStep } from '@/app/demos/stage/types'

/** Same sample as the demo editor; stats match `analyzeText` in `src/core/engines/text/analyze.ts`. */
export const TEXT_LINES = [
  'Good documentation answers the question before it is asked.',
  'It shows a working example first, then explains the parts.',
  'Short sentences help.',
  'So do headings that say what a section is for, and links to the next step.',
]

export const TEXT = TEXT_LINES.join('\n')

const WORDS_PER_MINUTE = 200

function round1(value: number): number {
  return Math.round(value * 10) / 10
}

function analyzeText(input: string) {
  const trimmed = input.trim()
  const words = trimmed ? trimmed.split(/\s+/).length : 0
  const sentences = trimmed ? (trimmed.match(/[.!?…]+(?=\s|$)/g) ?? []).length || 1 : 0
  const paragraphs = trimmed ? trimmed.split(/\n\s*\n/).filter(Boolean).length : 0
  const wordCharacters = trimmed ? trimmed.replace(/\s/g, '').length : 0
  const lines = input.split('\n')
  const blankLines = lines.filter((line) => line.trim() === '').length

  return {
    words,
    characters: input.length,
    charactersNoSpaces: input.replace(/\s/g, '').length,
    lines: lines.length,
    blankLines,
    nonBlank: lines.length - blankLines,
    paragraphs,
    sentences,
    readingTimeSeconds: Math.ceil((words / WORDS_PER_MINUTE) * 60),
    avgWordLength: words ? round1(wordCharacters / words) : 0,
    avgSentenceLength: sentences ? round1(words / sentences) : 0,
  }
}

export const STATS = analyzeText(TEXT)

export const WORDS_PER_MIN = WORDS_PER_MINUTE

/** Words per sentence for the heatmap (split on sentence boundaries). */
export const SENTENCE_LENGTHS = TEXT.trim()
  .split(/(?<=[.!?…])\s+/)
  .map((sentence) => sentence.split(/\s+/).filter(Boolean).length)

